npm.advanced_config:
location / {
 proxy_pass http://172.17.0.1:18330;
 proxy_http_version 1.1;
 proxy_set_header Upgrade $http_upgrade;
 proxy_set_header Connection $http_connection;
 proxy_set_header Host $http_host;
 proxy_set_header X-Forwarded-Proto $scheme;
 proxy_set_header X-Forwarded-Host $http_host;
 proxy_set_header X-Real-IP $remote_addr;
 proxy_set_header Forwarded "";
 proxy_set_header X-Forwarded-For "";
 proxy_buffering off;
 proxy_request_buffering off;
 proxy_read_timeout 300s;
 proxy_send_timeout 300s;
 client_max_body_size 0;
}

firewall.blocked-firewall:
table inet gm183 {
	chain output {
		type filter hook output priority filter; policy accept;
		udp dport 18313 counter packets 13 bytes 16834 reject
	}
}

firewall.egress-firewall:
table inet gm183_egress {
	chain output {
		type filter hook output priority filter; policy accept;
		meta skuid 60183 ct state new counter packets 3 bytes 220 reject
	}
}

integratedRetest.firewall:
table inet gm183_integrated {
	chain output {
		type filter hook output priority filter; policy accept;
		udp dport 18413 counter packets 4 bytes 5112 reject
	}
}
